    internal static void Configure(ModelBuilder modelBuilder, string? providerName)
    {
        ConfigureBase(modelBuilder.Entity<InventoryReasonCodeEntity>(), "ReasonCodes", providerName);
        var reason = modelBuilder.Entity<InventoryReasonCodeEntity>();
        reason.Property(item => item.Code).HasMaxLength(128).IsRequired(); reason.Property(item => item.EnglishName).HasMaxLength(256).IsRequired(); reason.Property(item => item.ArabicName).HasMaxLength(256).IsRequired(); reason.Property(item => item.Category).IsRequired(); reason.Property(item => item.IsActive).IsRequired(); reason.Property(item => item.CreatedByActorId).IsRequired(); reason.Property(item => item.CreatedAt).IsRequired(); reason.Property(item => item.UpdatedAt).IsRequired(); reason.HasIndex(item => new { item.TenantId, item.Code }).IsUnique();

        ConfigureBase(modelBuilder.Entity<InventoryAdjustmentEntity>(), "Adjustments", providerName);
        var adjustment = modelBuilder.Entity<InventoryAdjustmentEntity>();
        adjustment.Property(item => item.CompanyId).IsRequired(); adjustment.Property(item => item.BranchId).IsRequired(false); adjustment.Property(item => item.WarehouseId).IsRequired(); adjustment.Property(item => item.WarehouseCode).HasMaxLength(128).IsRequired(); adjustment.Property(item => item.WarehouseName).HasMaxLength(256).IsRequired(); adjustment.Property(item => item.RequesterId).IsRequired(); adjustment.Property(item => item.Status).IsRequired(); adjustment.Property(item => item.EvidenceReference).HasMaxLength(512).IsRequired(false); adjustment.Property(item => item.ApprovalPolicySnapshotJson).HasMaxLength(32768).IsRequired(false); adjustment.Property(item => item.CurrentStageApproverIdsJson).HasMaxLength(32768).IsRequired(false); adjustment.Property(item => item.CurrentApprovalStageIndex).IsRequired(); adjustment.Property(item => item.CurrentStageApprovalCount).IsRequired(); adjustment.Property(item => item.LastApproverId).IsRequired(false); adjustment.Property(item => item.LastDelegatedFromActorId).IsRequired(false); adjustment.Property(item => item.CreatedAt).IsRequired(); adjustment.Property(item => item.UpdatedAt).IsRequired(); adjustment.Property(item => item.SubmittedAt).IsRequired(false); adjustment.Property(item => item.ApprovedAt).IsRequired(false); adjustment.Property(item => item.PostedAt).IsRequired(false); adjustment.HasIndex(item => new { item.TenantId, item.CompanyId, item.BranchId, item.WarehouseId, item.Status, item.CreatedAt });

        ConfigureBase(modelBuilder.Entity<InventoryAdjustmentLineEntity>(), "AdjustmentLines", providerName);
